mapper.select:
SELECT g.id, g.inventory_id, g.biz_type, g.biz_no, g.warehouse_id, g.warehouse_area_id, g.warehouse_area_loca_id, g.consignor_id, g.sku_id, g.batch_number, g.change_count, g.before_count, g.after_count, g.remark, g.create_time, g.create_by, w.name AS warehouse_name, a.name AS area_name, l.loca_code, s.code AS sku_code, c.customer_name AS consignor_name FROM wms_inventory_log g LEFT JOIN wms_warehouse w ON w.id = g.warehouse_id LEFT JOIN wms_warehouse_area a ON a.id = g.warehouse_area_id LEFT JOIN wms_warehouse_area_loca l ON l.id = g.warehouse_area_loca_id LEFT JOIN wms_item_sku s ON s.id = g.sku_id LEFT JOIN wms_customer c ON c.id = g.consignor_id WHERE 1 = 1
AND g.inventory_id = #{q.inventoryId}
AND g.warehouse_id = #{q.warehouseId}
AND g.warehouse_area_loca_id = #{q.warehouseAreaLocaId}
AND g.sku_id = #{q.skuId}
AND g.batch_number = #{q.batchNumber}
AND g.biz_type = #{q.bizType}
AND g.biz_no LIKE CONCAT('%', #{q.bizNo}, '%')
AND g.create_time >= #{q.beginTime}
AND g.create_time <= #{q.endTime}
ORDER BY g.id DESC
